from lib import *
S = SS('h37')
steps = [
    step("同一个 Item 在线上的字节数(稳态:连接已建立,连续 200 次请求取平均,含 HTTP 头和帧头,两个方向合计;我写了一个只数字节的 TCP 代理)。小(id、name、count):gRPC 请求 97 + 响应 103 = 200 字节;HTTP/1.1 JSON 请求 227 + 响应 184 = 411 字节(2.06 倍);中(+10 个 tag、1 KiB payload):2394 对 3305 字节(1.38 倍);大(+64 KiB payload):131570 对 175358 字节(1.33 倍,bytes 在 JSON 里要 base64,膨胀约三分之一)。小消息的差距主要在 HTTP/1.1 每次请求都带完整的头(gRPC 靠 HTTP/2 的头压缩只发变化的部分)。", t=tl(S(1)), done=lidx(S(1), '大(+64 KiB payload)'), mark=lidx(S(1), '小(id、name、count)'), b=bars([['小:gRPC 字节', 200, '200'], ['小:JSON 字节', 411, '411'], ['大:gRPC 字节', 131570, '131570'], ['大:JSON 字节', 175358, '175358']], 180000, mark=[1, 3], done=[0, 2]), kv=KV([['小消息', 'JSON 是 gRPC 的 2.06 倍(头的开销)'], ['中等', '1.38 倍'], ['64 KiB', '1.33 倍(base64)']], ['小消息'])),
    step("单个调用者顺序请求的延迟(1 条连接,各 3000 次):小 Item:gRPC p50 70 µs、p99 136 µs;HTTP/1.1 JSON p50 72 µs、p99 154 µs(p50 之比 1.04,基本一样);64 KiB payload:gRPC p50 215 µs、p99 596 µs;HTTP/1.1 JSON p50 357 µs、p99 631 µs(p50 之比 1.66)。小消息的往返延迟没有明显差别,消息变大之后 JSON 的编解码和 base64 拖慢了 p50。要注意:这是 Go 的标准库 net/http + encoding/json 对 grpc-go,回环网络;换别的 JSON 库、别的语言差别会不同。", t=tl(S(2)), done=lidx(S(2), '64 KiB payload'), mark=lidx(S(2), '小 Item'), b=bars([['小:gRPC p50 µs', 70, '70'], ['小:JSON p50 µs', 72, '72'], ['64 KiB:gRPC p50 µs', 215, '215'], ['64 KiB:JSON p50 µs', 357, '357']], 380, mark=[1, 3], done=[0, 2]), kv=KV([['小 Item', 'p50 70 µs vs 72 µs,几乎没差别'], ['64 KiB', 'p50 215 µs vs 357 µs(1.66 倍)'], ['条件', 'Go 标准库,回环']], ['条件'])),
    step("64 个并发调用者(小 Item,各跑 2 秒):gRPC 1 条连接 90024 请求/秒(p50 667 µs);HTTP/1.1 JSON 限制 1 条连接(请求在连接上排队,一次只能一个在途):16484 请求/秒(p50 3824 µs);HTTP/1.1 放开到 64 条连接:87007 请求/秒(p50 549 µs)。也就是说 HTTP/1.1 想跑得和 gRPC 一样快,需要 64 条连接来换(每条连接一次只处理一个请求);gRPC 靠 HTTP/2 的多路复用用 1 条连接就够了。", t=tl(S(3)), done=lidx(S(3), '64 条连接'), mark=lidx(S(3), 'HTTP/1.1 JSON, 1 条连接'), b=bars([['gRPC 1 条连接 请求/秒', 90024, '90024'], ['HTTP/1.1 1 条连接', 16484, '16484'], ['HTTP/1.1 64 条连接', 87007, '87007']], 95000, mark=[1], done=[0, 2]), kv=KV([['gRPC', '1 条连接 90024 请求/秒'], ['HTTP/1.1,1 条', '16484 请求/秒(一次一个请求)'], ['HTTP/1.1,64 条', '87007 请求/秒(用连接数换)']], ['HTTP/1.1,64 条'])),
    step("新连接上第一次请求的耗时(建连 + 第一次请求,各 100 次的中位数):gRPC p50 256 µs;HTTP/1.1 JSON p50 146 µs。gRPC 建连更慢——要做 HTTP/2 前言、SETTINGS 交换,并且 grpc.NewClient 的连接管理有自己的状态机——所以不适合“每个请求新建一个连接”的用法(第 38 篇讲连接池)。这个结论只是本机回环上、小请求的比较。", t=tl(S(4)), done=lidx(S(4), 'gRPC:新连接'), mark=lidx(S(4), 'gRPC:新连接'), b=bars([['gRPC 新连接 + 第一次请求 µs', 256, '256'], ['HTTP/1.1 JSON µs', 146, '146']], 270, mark=[0], done=[1]), kv=KV([['gRPC', '256 µs'], ['HTTP/1.1 JSON', '146 µs'], ['含义', '别为每个请求新建连接']], ['含义'])),
]
A = mkarth('h37', 37, 'gRPC,HTTP/1.1,JSON,对比,延迟,字节数,多路复用,Go,真实验证,动画演示',
    '本机实测同一个 Item 用 gRPC 和 HTTP/1.1 JSON:小消息线上字节是 gRPC 的 2.06 倍、64 KiB 是 1.33 倍;小消息延迟几乎没差、64 KiB 的 p50 慢 1.66 倍;64 并发下 HTTP/1.1 一条连接只有 16484 请求/秒,要 64 条连接才追平;新连接上 gRPC 更慢。',
    'gRPC 比 HTTP/JSON 快多少?字节数少多少?快在什么地方、又在什么地方不快?这篇用 Go 标准库 net/http + encoding/json 对 grpc-go,在同一个 Item 上把字节数、延迟、并发、建连四个维度各比一遍。',
    [('2.06 倍', '小 Item 在线上,HTTP/1.1 JSON 相对 gRPC 的字节数'), ('16484 vs 90024', '64 并发下 HTTP/1.1 一条连接与 gRPC 一条连接的请求/秒'), ('146 µs vs 256 µs', '新连接上第一次请求,HTTP/1.1 JSON 比 gRPC 更快')],
    [('字节数', '<p>小消息主要差在 HTTP/1.1 每个请求重复发完整的头;大消息差在 JSON 的文本表示和 bytes 的 base64。</p>'),
     ('单个调用的延迟', '<p>小消息的往返延迟两者几乎一样;消息变大之后,JSON 的编解码和 base64 让延迟明显变长。</p>'),
     ('并发', '<p>HTTP/1.1 一条连接上一次只有一个请求在途,要用很多条连接换并发;gRPC 靠 HTTP/2 多路复用,一条连接就够。</p>'),
     ('建连', '<p>gRPC 新建连接比 HTTP/1.1 慢一些,不适合每个请求新建一个连接。以上都是同一台机器、回环网络上 Go 对 Go 的比较,不是普遍结论。</p>')],
    steps,
    [ENV_H + '。HTTP/JSON 一侧是 net/http + encoding/json,gRPC 一侧是 grpc-go + gwpb.Item;两个服务都在一个子进程里;字节数由我写的只数字节的 TCP 代理统计(每次写入增量累加);其余是本机回环的耗时,每档一次运行(并发那一节各 2 秒),有噪声',
     '没有验证:HTTP/2 + JSON(用 h2c 的同一个 JSON 服务)——它能把“多路复用”和“protobuf 编码”两个因素分开;TLS 开启时的比较;跨机器的真实网络;其它 JSON 库(如 jsoniter、sonic)或其它语言;请求头更多(Cookie、鉴权)时 HTTP/1.1 的字节数;流式和长连接场景'],
    '与 HTTP/JSON 的对比')
